def starts_one_ends(n):
    """
    Given a positive integer n, return the count of the numbers of n-digit
    positive integers that start or end with 1.
    """
    if n == 1:
        # Single-digit numbers that start or end with 1 are 1 itself.
        return 1
    else:
        # For n-digit numbers, the count is the sum of count of n-1-digit numbers
        # that start or end with 1 and count of n-1-digit numbers that start with 1.
        return 2 * (10 ** (n - 1)) - 10 ** (n - 2)

